/// <summary>
///     The <c>AVASalesTableListPageFrmCtr_AVAPurchOrderFormNum_Extension</c> class is the extension for <c>SalesTableListPage</c>
/// </summary>
[ExtensionOf(formControlStr(SalesTableListPage, AVAPurchOrderFormNum))]
final class AVASalesTableListPageFrmCtr_AVAPurchOrderFormNum_Extension
{
}

Method.Source:
/// <summary>
///     AVA <c>modified</c> method.
///     AVA - Schneider 05.06.2024
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean modified()
{
    boolean             retVal;

    FormDataSource      locSalesTable_ds;
    CustPurchaseOrder   locCustPurchaseOrder;

    retVal                  = next modified();

    locSalesTable_ds        = this.formRun().dataSource(tableStr(SalesTable));
    locCustPurchaseOrder    = this.valueStr();

    if (locCustPurchaseOrder)
    {
        SysQuery::findOrCreateRange(locSalesTable_ds.queryBuildDataSource(), fieldNum(SalesTable, PurchOrderFormNum)).value(SysQuery::valueLike(locCustPurchaseOrder));
    }
    else
    {
        SysQuery::findOrCreateRange(locSalesTable_ds.queryBuildDataSource(), fieldNum(SalesTable, PurchOrderFormNum)).value(SysQueryRangeUtil::valueUnlimited());
    }

    locSalesTable_ds.executeQuery();

    return retVal;
}
